	zip	varchar2(5)
);

/
--------------------------------------------------------
--  DDL for Type O_DEPT_TYPE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TYPE "SUMMIT"."O_DEPT_TYPE" as object
(
	deptno 	number,
	dname 	varchar2(14),
	loc		loc_type,
MEMBER FUNCTION
   total_sal RETURN NUMBER,
   pragma restrict_references(total_sal, WNDS, WNPS)
);
/
CREATE OR REPLACE EDITIONABLE TYPE BODY "SUMMIT"."O_DEPT_TYPE" as
MEMBER FUNCTION
   total_sal RETURN NUMBER is
   tot_sal number(7,2);
begin
   select sum(e.total_sal()) into tot_sal
   from o_emp e
   where e.deptref.deptno = self.deptno;

   return tot_sal;
end;

end;


/
--------------------------------------------------------
--  DDL for Type O_EMP_TYPE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TYPE "SUMMIT"."O_EMP_TYPE" as object
(EMPNO		NUMBER(4),
 ENAME		VARCHAR2(10),
 JOB		VARCHAR2(9),
 MGR		ref o_emp_type,
 HIREDATE       DATE,
 SAL		NUMBER(7,2),
 COMM		NUMBER(7,2),
 DEPTref	ref o_dept_type,

MEMBER FUNCTION
   total_sal RETURN NUMBER,
   pragma restrict_references(total_sal, WNDS, WNPS)
);
/
CREATE OR REPLACE EDITIONABLE TYPE BODY "SUMMIT"."O_EMP_TYPE" as
MEMBER FUNCTION
   total_sal RETURN NUMBER is
   tot_sal number(7,2);
begin
   tot_sal := nvl(self.sal,0) + nvl(self.comm,0);
   return tot_sal;
end;

end;


