--------------------------------------------------------
--  DDL for Procedure STATE_SUMMIT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "SUMMIT"."STATE_SUMMIT" IS
timestamp varchar2(50) ;
item_count NUMBER(5) ;
ord_count NUMBER(5) ;

BEGIN
   select to_char(sysdate , 'DD-MON-YY HH:MM:SS')
   into timestamp 
   from dual ;
   
  select count(*) 
  into item_count 
  from s_item Where ord_id >= 50000;

  select count(*) 
  into ord_count 
  from s_ord where id >= 50000;
  
  values ( timestamp , item_count , ord_count ) ;
  
  commit ;
  
   
END;

