--------------------------------------------------------
--  DDL for Package Body EMPHTML
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "SUMMIT"."EMPHTML" as
  procedure gethtml(ioemptab in out htmltab, iempno number) as
    hs varchar2(2000) := '';
    emprow EMP%ROWTYPE;
    deptrow DEPT%ROWTYPE;
  begin

    select * into emprow
    from emp
    where empno = iempno;

    select * into deptrow
    from dept
    where deptno = emprow.deptno;

    hs:=hs||'<HTML><BODY>';
    hs:=hs||'<FONT COLOR="BLUE" SIZE=+3>Employee <B><TT>'
          ||'<FONT COLOR="GREEN">'||initcap(emprow.ename)||'</FONT>'
          ||' </TT></B>Details</FONT><HR>';
    hs:=hs||'<TABLE BORDER=0>';
    hs:=hs||'<TR>';

    hs:=hs||'<TR><TD>Empno</TD><TD>'
          ||emprow.empno
          ||'</TD></TR>';


    -- perform some highlighting of the JOB

    if(emprow.job = 'MANAGER') then
      hs:=hs||'<TR><TD>Job</TD><TD><B><I>'
            ||initcap(emprow.job)
     	    ||'</I></B></TD></TR>';
    else
      hs:=hs||'<TR><TD>Job</TD><TD>'
            ||initcap(emprow.job)
            ||'</TD></TR>';
    end if;

    hs:=hs||'<TR><TD>Sal</TD><TD>$'
          ||emprow.sal
          ||'</TD></TR>';


    -- perform some highlighting of the COMMISION

    if(emprow.comm = 0) then
      hs:=hs||'<TR BGCOLOR="RED"><TD>Comm</TD><TD>$'
            ||emprow.comm
            ||'</TD></TR>';
    elsif(emprow.comm is NULL) then
      hs:=hs||'<TR><TD>Comm</TD><TD>N/A</TD></TR>';
    elsif((emprow.comm/emprow.sal) > .50) then
      hs:=hs||'<TR BGCOLOR="GREEN"><TD>Comm</TD><TD>$'
            ||emprow.comm
            ||'</TD></TR>';
    else
      hs:=hs||'<TR><TD>Comm</TD><TD>$'
            ||emprow.comm
            ||'</TD></TR>';
    end if;

    hs:=hs||'<TR><TD>Hiredate</TD><TD>'
          ||emprow.hiredate
          ||'</TD></TR>';
    hs:=hs||'<TR><TD>Department</TD><TD><I>'
          ||initcap(deptrow.dname)
          ||'</I></TD></TR>';
    hs:=hs||'</TABLE>';
    hs:=hs||'</HTML></BODY>';
    ioemptab(0).html := hs;
  end;

end;

/
--------------------------------------------------------
--  DDL for Function GET_PRODUCT_IMAGE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "SUMMIT"."GET_PRODUCT_IMAGE" (product_number IN NUMBER) RETURN VARCHAR2 IS
v_filename VARCHAR2(20);
BEGIN
       SELECT s_image.filename INTO v_filename
       FROM   s_image, s_product
       WHERE  s_image.id = s_product.image_id
              AND
              s_product.id = product_number;
       if v_filename is null then
          v_filename := 'No file';
       end if;
       RETURN v_filename;
EXCEPTION
       WHEN no_data_found THEN return('No file');
END;

