Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','WELCOME',1,1,'HEADING2','LEFT',null,'Welcome!');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','WELCOME',1,2,'TEXT1','FULL',null,'Welcome to the first issue of "The Oracle Speaks" - the newsletter for you, the customers of Oracle Corporation');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','THIS_ISSUE',1,3,'HEADING2','LEFT',null,'In This Issue:');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','THIS_ISSUE',1,4,'TEXT3','LEFT',null,' * Report''s New Features
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','NEW_EMP',1,5,'HEADING1','LEFT',null,'New Employees');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','NEW_EMP',1,6,'TEXT1','FULL',null,'If you haven''t already seen our financial report for the last quarter we have included excerpts from it in this month''s issue. As you will see from the results Oracle has had an exceptional quarter.');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','DEV_IMG',2,1,'IMAGE','LEFT','http://www.oracle.com','newslet.gif');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','TOP_STORY',2,2,'HEADING1','LEFT','http://www.oracle.com','Top Story');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','TOP_STORY',2,3,'TEXT1','FULL',null,'Oracle is pleased to announce the immediate availability of Developer Release 6.0.  This new feature packed release includes numerous enhancements and performance improvements.  Perhaps chief among the enhancements is the ability to utilize Oracle 8 objects.  Developers can now for the first time access, through Oracle Reports, Oracle 8 objects as if they were standard relational tables. We have also listened to your needs and increased the number of output options. With the same report definition you can output to PDF (Acrobat), HTML, HTMLCSS (Cascading style sheets ) and RTF (Rich Text Format ).  We have also enhanced the layout properties and added flush text support to give the right and left aligned effect you see in this newsletter.');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','FINANCIAL_RESULTS',3,1,'HEADING1','LEFT',null,'Financial Results');
Insert into SUMMIT.NEWS_LET (VOL,ISSUE,PAGE_NO,LANG,SECTION_NAME,COL_NUM,PRINT_ORD,COL_TYPE,JUST,URL,TEXT) values (1,1,1,'ENGLISH','FINANCIAL_RESULTS',3,2,'TEXT1','FULL',null,'Redwood Shores, Calif., September 10, 1998-Oracle Corporation today announced record first quarter results for the period ended August 31, 1998.  Revenues for the first quarter increased 28 percent (33 percent in local currencies) to $1.7 billion from $1.4 billion in the same period last year.  Net income for the period increased 30 percent to $195 million, or $0.20 per share, compared to net income of $150 million, or $0.15 per share, in the same period last year, excluding one-time charges for the acquisitions of Treasury Services Corporation and Navio Communications, Inc.  Giving effect to the one-time charges, net income for the previous period was $8 million.');
